import { JobCard, InventoryItem, BusinessSettings } from '../types';

export function generateMySqlSchema(): string {
  return `-- ============================================================
-- BOSCH & VENDOR POWER TOOLS SERVICE CENTER DATABASE SCHEMA
-- Target Engine: MySQL 8.0+ / MariaDB 10.5+ / PostgreSQL
-- Generated by AutoTrack Pro Transactional System
-- ============================================================

CREATE DATABASE IF NOT EXISTS \`bosch_service_db\` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE \`bosch_service_db\`;

-- 1. BUSINESS SETTINGS TABLE
CREATE TABLE IF NOT EXISTS \`business_settings\` (
  \`id\` INT AUTO_INCREMENT PRIMARY KEY,
  \`center_name\` VARCHAR(255) NOT NULL,
  \`address\` TEXT NOT NULL,
  \`phone\` VARCHAR(50) NOT NULL,
  \`email\` VARCHAR(100) NOT NULL,
  \`tax_rate\` DECIMAL(5,2) NOT NULL DEFAULT 10.00,
  \`labor_rate\` DECIMAL(10,2) NOT NULL DEFAULT 45.00,
  \`job_card_prefix\` VARCHAR(20) NOT NULL DEFAULT 'BOSCH-2026-',
  \`deduct_stock_on\` ENUM('Approval', 'InService', 'Completion') NOT NULL DEFAULT 'InService',
  \`updated_at\` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB;

-- 2. SPARE PARTS INVENTORY TABLE (1,000 SKUs)
CREATE TABLE IF NOT EXISTS \`inventory_items\` (
  \`id\` VARCHAR(64) PRIMARY KEY,
  \`sku\` VARCHAR(50) NOT NULL UNIQUE,
  \`barcode\` VARCHAR(50) NOT NULL,
  \`name\` VARCHAR(255) NOT NULL,
  \`category\` VARCHAR(100) NOT NULL,
  \`brand\` VARCHAR(100) NOT NULL,
  \`compatible_models\` VARCHAR(255) NOT NULL,
  \`unit_price\` DECIMAL(10,2) NOT NULL,
  \`cost_price\` DECIMAL(10,2) NOT NULL,
  \`stock_qty\` INT NOT NULL DEFAULT 0,
  \`min_stock_threshold\` INT NOT NULL DEFAULT 5,
  \`unit\` VARCHAR(20) NOT NULL DEFAULT 'pcs',
  \`bin_location\` VARCHAR(50) NOT NULL,
  \`last_restocked\` DATE NOT NULL,
  INDEX \`idx_category\` (\`category\`),
  INDEX \`idx_sku\` (\`sku\`),
  INDEX \`idx_stock_alert\` (\`stock_qty\`, \`min_stock_threshold\`)
) ENGINE=InnoDB;

-- 3. SERVICE JOB CARDS TABLE
CREATE TABLE IF NOT EXISTS \`job_cards\` (
  \`id\` VARCHAR(64) PRIMARY KEY,
  \`customer_name\` VARCHAR(255) NOT NULL,
  \`customer_company\` VARCHAR(255) NULL,
  \`customer_phone\` VARCHAR(50) NOT NULL,
  \`customer_email\` VARCHAR(100) NULL,
  \`gst_or_tax_id\` VARCHAR(50) NULL,
  
  -- Tool Specifications
  \`tool_brand\` VARCHAR(100) NOT NULL,
  \`tool_category\` VARCHAR(100) NOT NULL,
  \`tool_model_number\` VARCHAR(100) NOT NULL,
  \`tool_serial_number\` VARCHAR(100) NOT NULL,
  \`tool_voltage_rating\` VARCHAR(50) NOT NULL,
  \`tool_warranty_status\` VARCHAR(100) NOT NULL,
  \`tool_physical_condition\` TEXT NULL,
  \`tool_accessories_json\` JSON NULL,

  -- Grievance & Service Requirements
  \`grievance_category\` VARCHAR(150) NOT NULL,
  \`detailed_complaint\` TEXT NOT NULL,
  \`service_type\` VARCHAR(100) NOT NULL,
  \`pre_approved_limit\` DECIMAL(10,2) NOT NULL DEFAULT 50.00,

  -- Workflow & Status
  \`intake_date\` VARCHAR(50) NOT NULL,
  \`promised_completion\` VARCHAR(50) NOT NULL,
  \`status\` ENUM('Intake', 'Diagnosis', 'Awaiting Approval', 'In Service', 'Ready for Pickup', 'Completed', 'Cancelled') NOT NULL DEFAULT 'Intake',
  \`priority\` ENUM('Routine', 'Urgent', 'Emergency') NOT NULL DEFAULT 'Routine',
  \`technician\` VARCHAR(100) NOT NULL,
  \`diagnostic_notes\` TEXT NULL,

  -- Financials
  \`labor_hours\` DECIMAL(4,2) NOT NULL DEFAULT 1.00,
  \`labor_rate\` DECIMAL(10,2) NOT NULL DEFAULT 45.00,
  \`discount\` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
  \`tax_rate\` DECIMAL(5,2) NOT NULL DEFAULT 10.00,
  \`total_amount\` DECIMAL(10,2) NOT NULL DEFAULT 0.00,

  \`customer_signature\` LONGTEXT NULL,
  \`created_at\` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  \`updated_at\` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX \`idx_customer_phone\` (\`customer_phone\`),
  INDEX \`idx_status\` (\`status\`)
) ENGINE=InnoDB;

-- 4. JOB CARD PARTS LINK TABLE
CREATE TABLE IF NOT EXISTS \`job_card_parts\` (
  \`id\` INT AUTO_INCREMENT PRIMARY KEY,
  \`job_card_id\` VARCHAR(64) NOT NULL,
  \`part_id\` VARCHAR(64) NOT NULL,
  \`sku\` VARCHAR(50) NOT NULL,
  \`name\` VARCHAR(255) NOT NULL,
  \`unit_price\` DECIMAL(10,2) NOT NULL,
  \`quantity\` INT NOT NULL,
  \`total\` DECIMAL(10,2) NOT NULL,
  FOREIGN KEY (\`job_card_id\`) REFERENCES \`job_cards\`(\`id\`) ON DELETE CASCADE
) ENGINE=InnoDB;

-- 5. MESSAGE TRANSACTION LOGS TABLE
CREATE TABLE IF NOT EXISTS \`message_logs\` (
  \`id\` VARCHAR(64) PRIMARY KEY,
  \`job_card_id\` VARCHAR(64) NOT NULL,
  \`timestamp\` VARCHAR(50) NOT NULL,
  \`type\` VARCHAR(50) NOT NULL,
  \`recipient_phone\` VARCHAR(50) NOT NULL,
  \`text\` TEXT NOT NULL,
  \`channel\` ENUM('WhatsApp', 'SMS') NOT NULL,
  \`status\` VARCHAR(50) NOT NULL DEFAULT 'Sent',
  FOREIGN KEY (\`job_card_id\`) REFERENCES \`job_cards\`(\`id\`) ON DELETE CASCADE
) ENGINE=InnoDB;
`;
}

export function generateMySqlDump(
  jobCards: JobCard[],
  inventory: InventoryItem[],
  settings: BusinessSettings
): string {
  const schema = generateMySqlSchema();

  const escapeSql = (str: string | undefined | null) => {
    if (!str) return 'NULL';
    return `'${str.replace(/'/g, "''").replace(/\\/g, '\\\\')}'`;
  };

  let dump = `${schema}\n\n-- ====================================================\n-- TRANSACTIONAL DATA DUMP\n-- ====================================================\n\n`;

  // Insert Business Settings
  dump += `INSERT INTO \`business_settings\` (\`center_name\`, \`address\`, \`phone\`, \`email\`, \`tax_rate\`, \`labor_rate\`, \`job_card_prefix\`, \`deduct_stock_on\`) VALUES (\n  ${escapeSql(settings.centerName)},\n  ${escapeSql(settings.address)},\n  ${escapeSql(settings.phone)},\n  ${escapeSql(settings.email)},\n  ${settings.taxRate},\n  ${settings.laborRate},\n  ${escapeSql(settings.jobCardPrefix)},\n  ${escapeSql(settings.deductStockOn)}\n);\n\n`;

  // Insert Inventory Items
  dump += `-- INVENTORY ITEMS (${inventory.length} SKUs)\n`;
  inventory.forEach((i) => {
    dump += `INSERT INTO \`inventory_items\` (\`id\`, \`sku\`, \`barcode\`, \`name\`, \`category\`, \`brand\`, \`compatible_models\`, \`unit_price\`, \`cost_price\`, \`stock_qty\`, \`min_stock_threshold\`, \`unit\`, \`bin_location\`, \`last_restocked\`) VALUES (${escapeSql(i.id)}, ${escapeSql(i.sku)}, ${escapeSql(i.barcode)}, ${escapeSql(i.name)}, ${escapeSql(i.category)}, ${escapeSql(i.brand)}, ${escapeSql(i.compatibleModels)}, ${i.unitPrice}, ${i.costPrice}, ${i.stockQty}, ${i.minStockThreshold}, ${escapeSql(i.unit)}, ${escapeSql(i.binLocation)}, ${escapeSql(i.lastRestocked)});\n`;
  });

  dump += `\n-- JOB CARDS & PARTS (${jobCards.length} Cards)\n`;
  jobCards.forEach((j) => {
    const accJson = JSON.stringify(j.tool.accessoriesReceived || []);
    dump += `INSERT INTO \`job_cards\` (\`id\`, \`customer_name\`, \`customer_company\`, \`customer_phone\`, \`customer_email\`, \`gst_or_tax_id\`, \`tool_brand\`, \`tool_category\`, \`tool_model_number\`, \`tool_serial_number\`, \`tool_voltage_rating\`, \`tool_warranty_status\`, \`tool_physical_condition\`, \`tool_accessories_json\`, \`grievance_category\`, \`detailed_complaint\`, \`service_type\`, \`pre_approved_limit\`, \`intake_date\`, \`promised_completion\`, \`status\`, \`priority\`, \`technician\`, \`diagnostic_notes\`, \`labor_hours\`, \`labor_rate\`, \`discount\`, \`tax_rate\`, \`total_amount\`) VALUES (${escapeSql(j.id)}, ${escapeSql(j.customerName)}, ${escapeSql(j.customerCompany)}, ${escapeSql(j.customerPhone)}, ${escapeSql(j.customerEmail)}, ${escapeSql(j.gstOrTaxId)}, ${escapeSql(j.tool.brand)}, ${escapeSql(j.tool.category)}, ${escapeSql(j.tool.modelNumber)}, ${escapeSql(j.tool.serialNumber)}, ${escapeSql(j.tool.voltageRating)}, ${escapeSql(j.tool.warrantyStatus)}, ${escapeSql(j.tool.physicalCondition)}, ${escapeSql(accJson)}, ${escapeSql(j.serviceReq.grievanceCategory)}, ${escapeSql(j.serviceReq.detailedComplaint)}, ${escapeSql(j.serviceReq.serviceType)}, ${j.serviceReq.preApprovedLimit}, ${escapeSql(j.intakeDate)}, ${escapeSql(j.promisedCompletion)}, ${escapeSql(j.status)}, ${escapeSql(j.priority)}, ${escapeSql(j.technician)}, ${escapeSql(j.diagnosticNotes)}, ${j.laborHours}, ${j.laborRate}, ${j.discount}, ${j.taxRate}, ${j.totalAmount});\n`;

    j.parts.forEach((p) => {
      dump += `INSERT INTO \`job_card_parts\` (\`job_card_id\`, \`part_id\`, \`sku\`, \`name\`, \`unit_price\`, \`quantity\`, \`total\`) VALUES (${escapeSql(j.id)}, ${escapeSql(p.partId)}, ${escapeSql(p.sku)}, ${escapeSql(p.name)}, ${p.unitPrice}, ${p.quantity}, ${p.total});\n`;
    });
  });

  return dump;
}
